    private static readonly IReadOnlyDictionary<int, int> Values = Build();
    private static IReadOnlyDictionary<int, int> Build()
    {
        var data = Convert.FromBase64String(Packed);
        var result = new Dictionary<int, int>(data.Length / 4);
        for (var i = 0; i < data.Length; i += 4)
        {
            var scalar = data[i] << 8 | data[i + 1];
            var code = data[i + 2] << 8 | data[i + 3];
            var adjusted = code - (code <= 0x9FFC ? 0x8140 : 0xC140);
            result[scalar] = (adjusted >> 8) * 0xC0 + (adjusted & 255);
        }
        return result;
    }
    internal static int? Value(Rune scalar) => Values.TryGetValue(scalar.Value, out var value) ? value : null;
